    "title_en": "Between the Years",
    "verse": "사43:18-19",
    "quote": "너희는 이전 일을 기억하지 말며 옛날 일을 생각하지 말라 보라 내가 새 일을 행하리니 이제 나타낼 것이라 너희가 그것을 알지 못하겠느냐 반드시 내가 광야에 길을 사막에 강을 내리니",
    "body": "나는 지금 묵은해와 새해 사이에 서 있노라. 다가오는 한 해 위에 내 임재의 빛, 곧 의로운 태양의 광선을 비추고 지나간 해에 그림자를 던져 네 모든 괴로움과 슬픔과 실망을 덮으며 지난해와 새해 사이에 서 있노라.\n\n과거에 연연하지 말라. 오직 현재만 주시하라. 훗날 붉게 타오를 불꽃을 발산하기 위해 내 빛을 빨아들이고 사용하는 정도로만 네 과거를 사용하라. 오직 나로부터 받는 축복, 세상의 빛으로부터 오는 축복을 비축하라. 이런 것들을 생각하여 분발하라.\n\n미래에 대한 모든 두려움과 소중한 사람들의 궁핍에 대한 모든 염려와 고통과 실패에 대한 모든 근심을 파묻어라. 모든 몰 인정하고 비통한 생각, 증오와 원한, 패배 의식, 다른 사람들과 네 자신에 대한 실망, 우울함과 의기소침 이 모든 것을 파묻어라. 그리고 새로운 삶, 되살아난 삶을 향해 나아가라.\n\n세상이 보는 눈으로 보면 안 된다는 것을 기억하라. 모든 것을 내게 맡겨라. 앞으로 일어날 일들을 염려하거나 두려워한다면 내가 주는 선물을 기대할 수 없느니라. 내가 그날에 필요한 지혜와 힘을 공급하리니 너는 아무것도 염려하지 말라."
