    "body": "\"오직 여호와를 앙망하는 자는 새 힘을 얻으리니\"(사40:31)\n너는 새로워져야 하느니라. 다시 만들어져야 하느니라. 그리스도 나의 말이니라. 모든 것을 내게 맡겨라. 새 힘을 얻을 것이라. 오직 사랑만이 이기는 힘이니라. 두려워하지 말라. 내가 도우리라. 내 영이 흐르는 수로가 되어라. 내 영이 너를 통해 흐를 때 네 쓰라린 과거를 모두 쓸어가리라.\n\n마음을 다잡아라! 하나님이 사랑하시느니라. 너를 도우시며 너를 위해 싸우시느니라. 반드시 승리하시리니 네가 곧 알게 되리라.\n내가 사랑으로 모든 것을 계획하고 작정했으니, 그 생각과 계획이 펼쳐지는 것을 날마다 주목하라. 너는 아이가 되어라. 아이처럼 그저 배우기만 하라. 아이가 부모의 계획에 의문을 제기하지 않고 따르는 것처럼 기꺼이 받아들여라."
