    "title_en": "Sharp and Ready",
    "verse": "딤전4:7-8",
    "quote": "망령되고 허탄한 신화를 버리고 경건에 이르도록 네 자신을 연단하라 육체의 연단은 약간의 유익이 있으나 경건은 범사에 유익하니 금생과 내생에 약속이 있느니라",
    "body": "기도하라. 길이 열릴 것이라. 하나님께서 돌보시며 계획을 펼치시리니 그저  사랑하고 기다려라. 사랑은 열쇠이니 사랑으로 열지 못할 문은 없노라.\n무엇 때문에 염려하느냐?  하나님께서 너를 돌보고 보호하지 않으셨느냐? 계속 의지하라. 기쁜 마음으로 의지하라. 확신을 가지고 의지하며 잠잠하라. 내 능력 안에서 잠잠하라.\n\n기도하는 이 시간, 말씀을 묵상하는 이 시간, 훈련하고 연단하는 이 시간을 게을리 하지 말라. 이것은 너의 일이기도 하지만 너를 사용하기 위한 나의 일이기도 하느니라. 나의 도구는 예리하게 날이 서야 할지니 오직 그때에 사용할 수 있느니라. 어떤 희생을 치르더라도 너 자신을 훈련하여 최선의 상태로 만들어라.\n\n이렇게 할 때 네 모든 찰나의 생각들 조차도 응답받을 것이며, 네 모든 소망이 채워질 것이며, 네 모든 행동이 쓰임 받을 것이라. 이것은 두려운 능력, 강한 능력이니 잘못 구하지 않도록 언제나 유의하라. 내 영에 합하지 않은 것은 무엇도 구하지 않도록 조심하라.\n\n모든 해로운 생각들을 거부하라. 이적을 일으키는 능력이라도 그릇된 손에 들어가면 마법이 될 수 있으니 네 삶이 정결하고 선해야 하는 까닭이 바로 그것이라. 바로 지금 구하라. 그러면 즉시 받으리라. 훈련을 반겨라. 훈련하지 않으면 이런 능력을 결코 주지 아니하리니 오히려 해가 되기 때문이니라.\n다른 사람들의 삶을 염려하지 말라. 모든 것이 다 바르게 되리라.\n내가 주는 힘 안에서 자신을 완벽하게 훈련하는 것이 네가 가장 먼저해야 할 일이라."
