    "quote": "너는 마음을 다하여 여호와를 신뢰하고 네 명철을 의지하지 말라 너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라",
    "body": "나와 함께하는 삶은 고난이 면제된 삶이 아니니라. 그러나 너는 고난 가운데서도 평화를 얻으리라. 나는 종종 문을 닫음으로써 인간들을 인도하기도 하느니라. 사랑은 문을 열기도 하지만 닫기도 하느니라. 내 뜻을 믿고 신실한 마음으로 받아들이면 기뻐하기 어려운 상황에서도 기쁨이 넘치리라.\n\n내 종 바울이 \"우리의 잠시 받는 환난의 경한 것이 지극히 크고 영원한 영광의 중한 것을 우리에게 이루게 함이니\"(고후4:17)라고 말한 것도 '닫힌 문'의 교훈을 깨달았기 때문이 아니겠느냐? 이를 깨닫지 못하면 좌절할 수밖에 없나니 명심하고 또 명심하라. 기쁨은 고요함의 소산이니라."
